"""Duration parsing."""

import re


_PLAIN_SECONDS = re.compile(r"[0-9]+\Z")
_COMPONENT = re.compile(r"([0-9]+)(ms|[dhms])")
_UNITS = {"d": (0, 86400), "h": (1, 3600), "m": (2, 60), "s": (3, 1), "ms": (4, 0.001)}


def parse_duration(text: str) -> float:
    """Return seconds from an integer or descending duration components."""
    if not isinstance(text, str):
        raise TypeError("duration must be a string")

    stripped = text.strip()
    if _PLAIN_SECONDS.fullmatch(stripped):
        return float(stripped)

    total = 0.0
    position = 0
    previous_rank = -1
    while position < len(stripped):
        component = _COMPONENT.match(stripped, position)
        if component is None:
            raise ValueError(f"unsupported duration: {text!r}")
        rank, factor = _UNITS[component.group(2)]
        if rank <= previous_rank:
            raise ValueError(f"unsupported duration: {text!r}")
        total += int(component.group(1)) * factor
        previous_rank = rank
        position = component.end()
        while position < len(stripped) and stripped[position].isspace():
            position += 1

    if previous_rank < 0:
        raise ValueError(f"unsupported duration: {text!r}")
    return float(total)
